def summarize_logs(lines):
    from collections import Counter

    level_counts = {"INFO": 0, "WARN": 0, "ERROR": 0}
    word_counter = Counter()

    for line in lines:
        parts = line.split()
        if len(parts) < 3:
            continue

        # Extract level (second token) and message (remaining tokens after level)
        level = parts[1]
        if level in level_counts:
            level_counts[level] += 1

        # Message words: everything after the level token
        message_words = parts[2:]
        for word in message_words:
            word_lower = word.lower()
            if word_lower:
                word_counter[word_lower] += 1

    top_words = [word for word, _ in word_counter.most_common(3)]

    return {
        "level_counts": level_counts,
        "top_words": top_words
    }
